mapper.sql:
WHERE w.type IN ('MATERIAL', 'FACTORY')
AND w.type = #{q.warehouseType}
AND s.warehouse_id = #{q.warehouseId}

choose.when:


(
    SELECT sk.* FROM inv_stock sk WHERE sk.material_sku_id IN (
        SELECT mk.id FROM bas_material_sku mk WHERE upper(mk.code) LIKE #{keywordPrefix}
        OR upper(mk.code) IN #{code}
        UNION
        SELECT mk.id FROM bas_material_sku mk JOIN bas_material mm ON mm.id = mk.material_id
        WHERE upper(mm.code) LIKE #{keywordPrefix} OR mm.name ILIKE #{keywordContains}
        OR upper(mm.code) IN #{code}
    )
    UNION
    SELECT sw.* FROM inv_stock sw JOIN bas_warehouse mw ON mw.id = sw.warehouse_id
    WHERE mw.name ILIKE #{keywordContains}
)
